// API service for handling all API calls
export const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';

// Create axios instance with default config
import axios from 'axios';
const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
  },
  withCredentials: true,
  timeout: 10000, // 10 seconds
});

// Request interceptor for API calls
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('access_token');
    if (token) {
      config.headers['Authorization'] = `Bearer ${token}`;
    }

    // Log request
    console.log(`[API] ${config.method.toUpperCase()} ${config.url}`, {
      headers: config.headers,
      data: config.data,
      params: config.params,
    });

    return config;
  },
  (error) => {
    console.error('[API] Request error:', error);
    return Promise.reject(error);
  }
);

// Response interceptor for API calls
api.interceptors.response.use(
  (response) => {
    // Log successful response
    console.log(`[API] ${response.config.method.toUpperCase()} ${response.config.url} - ${response.status}`, {
      data: response.data,
      headers: response.headers,
    });
    return response;
  },
  async (error) => {
    const originalRequest = error.config;

    // Log error response
    console.error('[API] Response error:', {
      url: originalRequest?.url,
      method: originalRequest?.method,
      status: error.response?.status,
      data: error.response?.data,
    });

    // Handle 401 Unauthorized
    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;

      try {
        // Try to refresh the token
        const { access_token } = await refreshToken();

        if (access_token) {
          // Update the authorization header
          originalRequest.headers['Authorization'] = `Bearer ${access_token}`;

          // Retry the original request with the new token
          return api(originalRequest);
        }
      } catch (refreshError) {
        console.error('[API] Token refresh failed:', refreshError);
        // Clear tokens and redirect to login
        localStorage.removeItem('access_token');
        localStorage.removeItem('refresh_token');
        window.location.href = '/login';
      }
    }

    return Promise.reject(error);
  }
);

export default api;

// Helper function to get auth headers
export const getAuthHeaders = () => {
  const token = localStorage.getItem('access_token');
  return {
    'Authorization': token ? `Bearer ${token}` : '',
    'Content-Type': 'application/json',
    'Accept': 'application/json',
  };
};

// Export refreshToken for use in other files
import { refreshToken } from './auth';
export { refreshToken };

// Helper function to handle API responses
const handleResponse = async (response) => {
  // Handle 401 Unauthorized
  if (response.status === 401) {
    // Clear auth and redirect to login
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    window.location.href = '/login';
    return;
  }

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    const error = new Error(data.message || `HTTP error! status: ${response.status}`);
    error.status = response.status;
    error.data = data;
    throw error;
  }

  return data;
};

// Helper function to make authenticated requests
const fetchWithAuth = async (url, options = {}) => {
  const headers = {
    'Content-Type': 'application/json',
    ...getAuthHeaders(),
    ...(options.headers || {})
  };

  const response = await fetch(url, {
    ...options,
    headers,
    credentials: 'include', // Important for cookies
  });

  return handleResponse(response);
};

// Appointment API
export const appointmentApi = {
  // Create a new appointment
  createAppointment: async (appointmentData) => {
    return fetchWithAuth(`${API_BASE_URL}/api/appointments`, {
      method: 'POST',
      body: JSON.stringify(appointmentData),
    });
  },

  // Get available time slots for a given date
  getAvailableSlots: async (date) => {
    return fetchWithAuth(
      `${API_BASE_URL}/api/appointments/availability?date=${date.toISOString().split('T')[0]}`
    );
  },

  // Get all appointments (for admin view)
  getAppointments: async (params = {}) => {
    const query = new URLSearchParams(params).toString();
    return fetchWithAuth(`${API_BASE_URL}/api/appointments?${query}`);
  },

  // Update appointment status
  updateAppointmentStatus: async (appointmentId, status) => {
    return fetchWithAuth(`${API_BASE_URL}/api/appointments/${appointmentId}/status`, {
      method: 'PATCH',
      body: JSON.stringify({ status }),
    });
  },

  // Cancel an appointment
  cancelAppointment: async (appointmentId) => {
    return fetchWithAuth(`${API_BASE_URL}/api/appointments/${appointmentId}`, {
      method: 'DELETE',
    });
  },
};

// Add more API services as needed
export const authApi = {
  login: async (credentials) => {
    const response = await fetch(`${API_BASE_URL}/auth/login`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(credentials),
    });
    return handleResponse(response);
  },

  // Add other auth-related methods
};

// Add more API services as needed (e.g., for services, users, etc.)
